// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

//////////////////////////
/// Type Declarations ////
//////////////////////////
/**
 * @dev Market lifecycle:
 * - OPEN: Trading permitted
 * - CLOSED: Trading halted, awaiting oracle resolution
 * - RESOLVED: Oracle has finalized outcome, users can redeem
 * - SETTLED: Redemption window closed, no more redemptions allowed
 */
enum MarketState {
    OPEN,
    CLOSED,
    RESOLVED,
    SETTLED
}

enum Outcome {
    INVALID,  
    YES,
    NO
}

struct TradeQuote {
    address trader;
    address market;
    Outcome outcome;
    uint256 amount;
    uint256 cost;
    uint256 deadline;
    uint256 nonce;
    bool isSell;
    uint256 minAmountOut; // for buys: minimum outcome tokens expected
    uint256 minReturn; // for sells: minimum ETH expected
}

src/Market.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title Market
 * @author Rahul Dindigala
 * @notice A binary prediction market contract that manages trading, state transitions, and outcome tokens
 * @dev This contract handles the lifecycle of a prediction market from creation to settlement
 */
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

import {OutcomeToken} from "./OutcomeToken.sol";
import {MarketState, Outcome, TradeQuote} from "./MarketTypes.sol";
import {Vault} from "./Vault.sol";
import {QuoteVerifier} from "./QuoteVerifier.sol";

contract Market is ReentrancyGuard {
    //////////////////////////
    /// STATE VARIABLES //////
    //////////////////////////
    uint256 private constant PAYOUT_PER_TOKEN = 1 ether;

    Vault public immutable i_vault;
    QuoteVerifier public immutable i_quoteVerifier;
    OutcomeToken public immutable i_yesToken;
    OutcomeToken public immutable i_noToken;

    address public immutable i_oracle;
    address public immutable i_settlementEngine;

    MarketState public state;
    uint256 public immutable i_endTime;
    uint256 public immutable i_lmsrB; // LMSR liquidity parameter for pricing
    Outcome public resolvedOutcome = Outcome.INVALID; // YES, NO, or INVALID (default)

    mapping(bytes32 quoteHash => bool isUsed) public usedQuoteHashes;

    //////////////////////////
    /// EVENTS //////
    //////////////////////////
    event TradeExecuted(
        address indexed trader, Outcome indexed outcome, uint256 indexed amount, uint256 cost, bytes32 quoteHash
    );

    event MarketClosed(uint256 indexed timestamp);
    event MarketResolved(Outcome indexed outcome);
    event MarketSettled(uint256 indexed timestamp);

    //////////////////////////
    /// ERRORS //////
    //////////////////////////
    error Market__MarketNotOpen();
    error Market__MarketNotResolved();
    error Market__InvalidETHAmount();
    error Market__MarketNotExpired();
    error Market__QuoteAlreadyUsed();
    error Market__Unauthorized();
    error Market__MarketNotClosed();
    error Market__InvalidAddress();
    error Market__SlippageExceeded();
    error Market__OutcomeConflict();
    error Market__UnauthorizedNotOracle();
    error Market__UnauthorizedNotSettlementEngine();

    //////////////////////////
    /// MODIFIERS //////
    //////////////////////////
    modifier onlyOracle() {
        if (msg.sender != i_oracle) {
            revert Market__UnauthorizedNotOracle();
        }
        _;
    }

    modifier onlySettlementEngine() {
        if (msg.sender != i_settlementEngine) {
            revert Market__UnauthorizedNotSettlementEngine();
        }
        _;
    }

    modifier onlyOpen() {
        _ensureClosedIfExpired();

        if (state != MarketState.OPEN) {
            revert Market__MarketNotOpen();
        }
        _;
    }

    // modifier notExpired() {
    //     if (block.timestamp >= i_endTime) {
    //         revert Market__MarketExpired();
    //     }
    //     _;
    // }

    //////////////////////////
    /// FUNCTIONS //////
    //////////////////////////
    /**
     * @notice Initialize a new prediction market
     * @param _vault Address of the Vault contract for ETH custody
     * @param _quoteVerifier Address of the QuoteVerifier contract
     * @param _settlementEngine Address of the SettlementEngine contract
     * @param _endTime Unix timestamp when the market expires
     * @param _lmsrB LMSR liquidity parameter (b value)
     */
    constructor(
        address _vault,
        address _quoteVerifier,
        address _oracle,
        address _settlementEngine,
        uint256 _endTime,
        uint256 _lmsrB
    ) {
        if (
            _vault == address(0) || _quoteVerifier == address(0) || _oracle == address(0)
                || _settlementEngine == address(0)
        ) {
            revert Market__InvalidAddress();
        }
        if (_lmsrB == 0) {
            revert Market__InvalidAddress(); // Using same error for clarity
        }

        i_oracle = _oracle;
        i_settlementEngine = _settlementEngine;
        i_vault = Vault(_vault);
        i_quoteVerifier = QuoteVerifier(_quoteVerifier);
        i_endTime = _endTime;
        i_lmsrB = _lmsrB;

        i_yesToken = new OutcomeToken("Yes Token", "YES", address(this), _settlementEngine);
        i_noToken = new OutcomeToken("No Token", "NO", address(this), _settlementEngine);

        state = MarketState.OPEN;
    }

    //////////////////////////
    /// External Functions ///
    //////////////////////////
    /**
     * @notice Execute a trade by purchasing outcome tokens
     * @dev Verifies the quote signature, checks slippage, mints tokens, and deposits ETH to vault
     * @param quote The trade quote containing trade details
     * @param signature The EIP-712 signature of the quote
     * @param minAmountOut Minimum amount of tokens expected (slippage protection)
     * @custom:reverts Market__InvalidETHAmount If sent ETH doesn't match quote cost
     * @custom:reverts Market__QuoteAlreadyUsed If quote hash was already used
     * @custom:reverts Market__SlippageExceeded If received tokens are less than minAmountOut
     */
    function executeTrade(TradeQuote calldata quote, bytes calldata signature, uint256 minAmountOut, uint256 minReturn)
        external
        payable
        nonReentrant
        onlyOpen
    {
        // Caller must be the intended trader
        if (msg.sender != quote.trader) {
            revert Market__Unauthorized();
        }

        if (!quote.isSell) {
            if (msg.value != quote.cost) {
                revert Market__InvalidETHAmount();
            }
        } else {
            // sell trades must not send ETH
            if (msg.value != 0) {
                revert Market__InvalidETHAmount();
            }
        }

        bytes32 quoteHash = i_quoteVerifier.verifyTradeQuote(quote, signature);

        if (usedQuoteHashes[quoteHash]) {
            revert Market__QuoteAlreadyUsed();
        }
        usedQuoteHashes[quoteHash] = true;

        // Update nonce after successful verification
        i_quoteVerifier.updateNonce(quote.trader, address(this), quote.nonce);

        if (!quote.isSell) {
            // Slippage protection: ensure user receives at least minAmountOut tokens
            if (quote.amount < minAmountOut) {
                revert Market__SlippageExceeded();
            }

            if (quote.outcome == Outcome.YES) {
                i_yesToken.mint(msg.sender, quote.amount);
            } else {
                i_noToken.mint(msg.sender, quote.amount);
            }

            // deposit ETH into the vault for this market
            i_vault.deposit{value: msg.value}(address(this));
        } else {
            // SELL: burn user's outcome tokens and refund ETH from vault
            uint256 refund = quote.cost;
            if (refund < minReturn) {
                revert Market__SlippageExceeded();
            }

            if (quote.outcome == Outcome.YES) {
                i_yesToken.burnFromUser(msg.sender, quote.amount);
            } else {
                i_noToken.burnFromUser(msg.sender, quote.amount);
            }

            // withdraw refund from vault to trader
            i_vault.marketWithdraw(msg.sender, refund);
        }

        emit TradeExecuted(msg.sender, quote.outcome, quote.amount, quote.cost, quoteHash);
    }

    /**
     * @notice Manually close the market after expiration
     * @dev Can be called by anyone once the market has expired
     * @custom:reverts Market__MarketNotExpired If market hasn't expired yet
     * @custom:reverts Market__MarketNotOpen If market is not in OPEN state
     */
    function closeMarket() external {
        if (state == MarketState.CLOSED) {
            return;
        }

        if (block.timestamp < i_endTime) {
            revert Market__MarketNotExpired();
        }
        if (state != MarketState.OPEN) {
            revert Market__MarketNotOpen();
        }

        state = MarketState.CLOSED;
        emit MarketClosed(block.timestamp);
    }

    /**
     * @notice Resolve the market with a final outcome (callback from SettlementEngine)
     * @dev Only callable by SettlementEngine. Passive state receiver pattern.
     * @param outcome The final oracle-determined outcome (YES or NO)
     * @custom:reverts Market__Unauthorized If caller is not SettlementEngine
     */
    function onResolved(Outcome outcome) external onlyOracle {
        if (state != MarketState.CLOSED) {
            revert Market__MarketNotClosed();
        }

        if (resolvedOutcome != Outcome.INVALID && resolvedOutcome != outcome) {
            revert Market__OutcomeConflict();
        }

        resolvedOutcome = outcome;
        state = MarketState.RESOLVED;
        emit MarketResolved(outcome);
    }

    /**
     * @notice Mark market as fully settled (30+ days after resolution)
     * @dev Only callable by SettlementEngine after redemption window closes
     * @custom:reverts Market__Unauthorized If caller is not SettlementEngine
     */
    function onSettled() external onlySettlementEngine {
        if (state != MarketState.RESOLVED) {
            revert Market__MarketNotResolved();
        }
        state = MarketState.SETTLED;
        emit MarketSettled(block.timestamp);
    }

    //////////////////////////
    /// Internal Functions ///
    //////////////////////////

    /**
     * @notice Auto-close market if expired
     * @dev Internal helper to ensure market state is updated when expired. Called automatically in modifiers.
     */
    function _ensureClosedIfExpired() internal {
        if (state == MarketState.OPEN && block.timestamp >= i_endTime) {
            state = MarketState.CLOSED;
            emit MarketClosed(block.timestamp);
        }
    }

    //////////////////////////
    /// View Functions ///
    //////////////////////////
    /**
     * @notice Get the address of the winning token for a given outcome
     * @param outcome The outcome to check (YES or NO)
     * @return address The address of the corresponding outcome token
     */
    function winningToken(Outcome outcome) external view returns (address) {
        return outcome == Outcome.YES ? address(i_yesToken) : address(i_noToken);
    }

    /**
     * @notice Get the payout rate per token
     * @return uint256 The amount of ETH paid per outcome token (1 ether)
     */
    function payoutRate() external pure returns (uint256) {
        return PAYOUT_PER_TOKEN;
    }

    /**
     * @notice Check if market is closed or expired
     * @dev View function to check market readiness for settlement
     * @return bool True if market is closed or expired
     */
    function isClosedOrExpired() external view returns (bool) {
        return state == MarketState.CLOSED || block.timestamp >= i_endTime;
    }

    /**
     * @notice Get comprehensive market information
     * @return state_ Current market state (OPEN, CLOSED, RESOLVED, or SETTLED)
     * @return endTime_ Unix timestamp when market expires
     * @return yesToken_ Address of the YES outcome token
     * @return noToken_ Address of the NO outcome token
     * @return vault_ Address of the vault holding market ETH
     * @return lmsrB_ LMSR parameter b
     * @return isClosed_ Whether the market is closed or expired
     */
    function getMarketInfo()
        external
        view
        returns (
            MarketState state_,
            uint256 endTime_,
            address yesToken_,
            address noToken_,
            address vault_,
            uint256 lmsrB_,
            bool isClosed_
        )
    {
        return (
            state,
            i_endTime,
            address(i_yesToken),
            address(i_noToken),
            address(i_vault),
            i_lmsrB,
            state == MarketState.CLOSED || block.timestamp >= i_endTime
        );
    }
}

src/MarketFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title MarketFactory
 * @author Rahul Dindigala
 * @notice Factory contract for creating and managing prediction markets
 * @dev Handles market creation, whitelisting, creator subsidies, and prevents duplicate markets
 */
import {Market} from "./Market.sol";
import {Vault} from "./Vault.sol";
import {OracleAdapter} from "./OracleAdapter.sol";
import {OracleBudget} from "./OracleBudget.sol";
import {PlatformTreasury} from "./PlatformTreasury.sol";
import {QuoteVerifier} from "./QuoteVerifier.sol";
import {SettlementEngine} from "./SettlementEngine.sol";

contract MarketFactory {
    //////////////////////////
    /// STATE VARIABLES ///
    //////////////////////////
    uint256 public constant MAX_MARKET_DURATION = 365 days;
    uint256 public constant MARKET_CREATION_FEE = 0.03 ether;

    Vault public immutable i_vault;
    OracleAdapter public immutable i_oracle;
    OracleBudget public immutable i_oracleBudget;
    PlatformTreasury public immutable i_platformTreasury;
    QuoteVerifier public immutable i_quoteVerifier;
    SettlementEngine public immutable i_settlementEngine;
    address public i_owner;

    // Whitelisted market creators
    mapping(address creator => bool isWhitelisted) public whitelistedCreators;

    // Track creator deposits (subsidy tracking)
    mapping(address market => address creator) public marketCreator;
    mapping(address market => uint256 subsidy) public marketSubsidy;

    mapping(address market => bytes32 mateHash) public marketToMetadataHash;

    /// metadata hash → market (prevent duplicates)
    mapping(bytes32 metaHash => address market) public metadataHashToMarket;

    address[] public markets;

    //////////////////////////
    /// EVENTS ///
    event MarketCreated(
        address indexed market, bytes32 indexed metadataHash, uint256 indexed endTime, address creator, uint256 subsidy
    );
    event CreatorWhitelisted(address indexed creator, bool isWhitelisted);

    //////////////////////////
    /// ERRORS ///
    //////////////////////////
    error MarketFactory__DuplicateMarket();
    error MarketFactory__InvalidEndTime();
    error MarketFactory__InvalidAddress();
    error MarketFactory__DurationTooLong();
    error MarketFactory__NotWhitelisted();
    error MarketFactory__InsufficientFee();
    error MarketFactory__InvalidSubsidy();
    error MarketFactory__Unauthorized();

    //////////////////////////
    /// MODIFIERS ///
    //////////////////////////
    modifier onlyOwner() {
        if (msg.sender != i_owner) {
            revert MarketFactory__Unauthorized();
        }
        _;
    }

    //////////////////////////
    /// FUNCTIONS ///
    //////////////////////////

    /**
     * @notice Initialize the MarketFactory contract
     * @param _vault Address of the Vault contract
     * @param _oracle Address of the OracleAdapter contract
     * @param _oracleBudget Address of the OracleBudget contract
     * @param _platformTreasury Address of the PlatformTreasury contract
     * @param _quoteVerifier Address of the QuoteVerifier contract
     * @param _settlementEngine Address of the SettlementEngine contract
     * @param _owner Address that will own the contract
     */
    constructor(
        address _vault,
        address _oracle,
        address payable _oracleBudget,
        address payable _platformTreasury,
        address _quoteVerifier,
        address _settlementEngine,
        address _owner
    ) {
        if (
            _vault == address(0) || _oracle == address(0) || _oracleBudget == address(0)
                || _platformTreasury == address(0) || _quoteVerifier == address(0) || _settlementEngine == address(0)
                || _owner == address(0)
        ) {
            revert MarketFactory__InvalidAddress();
        }
        i_vault = Vault(_vault);
        i_oracle = OracleAdapter(_oracle);
        i_oracleBudget = OracleBudget(_oracleBudget);
        i_platformTreasury = PlatformTreasury(_platformTreasury);
        i_quoteVerifier = QuoteVerifier(_quoteVerifier);
        i_settlementEngine = SettlementEngine(_settlementEngine);
        i_owner = _owner;
    }

    //////////////////////////
    /// External Functions ///
    //////////////////////////

    /**
     * @notice Whitelist or remove a market creator
     * @param creator Address of the market creator
     * @param allowed True to whitelist, false to revoke
     */
    function setCreatorWhitelist(address creator, bool allowed) external onlyOwner {
        if (creator == address(0)) {
            revert MarketFactory__InvalidAddress();
        }
        whitelistedCreators[creator] = allowed;
        emit CreatorWhitelisted(creator, allowed);
    }

    /**
     * @notice Create a new prediction market with subsidy
     * @dev Creator must be whitelisted. Requires creation fee (0.03 ETH) and subsidy deposit.
     *      Subsidy = b * ln(2) ensures LMSR solvency.
     *      Fee split: 0.02 ETH -> OracleBudget, 0.01 ETH -> PlatformTreasury
     * @param metadataHash Hash of the market metadata (used to prevent duplicates)
     * @param endTime Unix timestamp when the market expires
     * @param lmsrB LMSR liquidity parameter (b value)
     * @param subsidyAmount Creator's subsidy deposit (should equal b * ln(2) ≈ 0.693 * b)
     * @return market Address of the newly created market contract
     * @custom:reverts MarketFactory__NotWhitelisted If creator is not whitelisted
     * @custom:reverts MarketFactory__InsufficientFee If ETH sent doesn't cover fee + subsidy
     * @custom:reverts MarketFactory__InvalidSubsidy If subsidy is insufficient
     * @custom:reverts MarketFactory__DuplicateMarket If market with same metadataHash exists
     * @custom:reverts MarketFactory__InvalidEndTime If endTime is invalid
     * @custom:reverts MarketFactory__DurationTooLong If market duration exceeds limit
     */
    function createMarket(bytes32 metadataHash, uint256 endTime, uint256 lmsrB, uint256 subsidyAmount)
        external
        payable
        returns (address market)
    {
        // Verify creator is whitelisted
        if (!whitelistedCreators[msg.sender]) {
            revert MarketFactory__NotWhitelisted();
        }

        // Verify payment covers creation fee + subsidy
        uint256 totalRequired = MARKET_CREATION_FEE + subsidyAmount;
        if (msg.value < totalRequired) {
            revert MarketFactory__InsufficientFee();
        }

        // Validate subsidy is reasonable (b * ln(2) = 0.693 * b)
        // Minimum check: subsidy should be at least 69% of b
        uint256 minSubsidy = (lmsrB * 69) / 100;
        if (subsidyAmount < minSubsidy) {
            revert MarketFactory__InvalidSubsidy();
        }

        // Verify metadata and timing
        if (metadataHashToMarket[metadataHash] != address(0)) {
            revert MarketFactory__DuplicateMarket();
        }
        if (endTime <= block.timestamp) {
            revert MarketFactory__InvalidEndTime();
        }
        if (endTime > block.timestamp + MAX_MARKET_DURATION) {
            revert MarketFactory__DurationTooLong();
        }

        // Deploy market
        market = address(
            new Market(
                address(i_vault),
                address(i_quoteVerifier),
                address(i_oracle),
                address(i_settlementEngine),
                endTime,
                lmsrB
            )
        );

        // Track creator and subsidy
        marketCreator[market] = msg.sender;
        marketSubsidy[market] = subsidyAmount;

        // Register market
        marketToMetadataHash[market] = metadataHash;
        metadataHashToMarket[metadataHash] = market;
        markets.push(market);

        // Register market with vault
        i_vault.registerMarket(market);

        // Deposit subsidy into vault for market
        i_vault.deposit{value: subsidyAmount}(market);

        // Route creation fee: 0.02 ETH -> OracleBudget, 0.01 ETH -> PlatformTreasury
        uint256 oracleBounty = 0.02 ether;
        uint256 platformFee = 0.01 ether;

        i_oracleBudget.fundMarketBounty{value: oracleBounty}(market, oracleBounty);
        i_platformTreasury.depositCreationFee{value: platformFee}(market);

        // Refund any excess ETH
        if (msg.value > totalRequired) {
            (bool success,) = msg.sender.call{value: msg.value - totalRequired}("");
            require(success, "Refund failed");
        }

        emit MarketCreated(market, metadataHash, endTime, msg.sender, subsidyAmount);
    }

    ////////////////////////
    /// View Functions ///
    //////////////////////////
    /**
     * @notice Get all created market addresses
     * @return address[] Array of all market addresses
     */
    function getAllMarkets() external view returns (address[] memory) {
        return markets;
    }

    /**
     * @notice Get the metadata hash for a specific market
     * @param market The market address to query
     * @return bytes32 The metadata hash associated with the market
     */
    function getMarketMetadataHash(address market) external view returns (bytes32) {
        return marketToMetadataHash[market];
    }

    /**
     * @notice Check if an address is a valid market created by this factory
     * @param market The address to check
     * @return bool True if the address is a valid market
     */
    function isValidMarket(address market) external view returns (bool) {
        return marketToMetadataHash[market] != bytes32(0);
    }
}

